using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<OrdersDb>(o => o.UseSqlServer(builder.Configuration.GetConnectionString("orders")));
builder.Services.AddQueuePolicy(o => { o.MaxConcurrentRequests = 50; o.RequestQueueLimit = 100; });

var app = builder.Build();
app.UseConcurrencyLimiter();
app.MapGet("/orders/{id:int}", async (int id, OrdersDb db) => await db.Orders.FindAsync(id) is { } o ? Results.Ok(o) : Results.NotFound());
app.Run();

public sealed class OrdersDb(DbContextOptions<OrdersDb> options) : DbContext(options)
{
    public DbSet<Order> Orders => Set<Order>();
}

public sealed record Order(int Id, string Customer);

