const todos = [];
function render() {
  document.getElementById('list').replaceChildren(...todos.map(t => Object.assign(document.createElement('li'), { textContent: t.text })));
}
function addTodo(text) {
  const todo = { id: crypto.randomUUID(), text: String(text).slice(0, 200) };
  todos.push(todo);
  render();
  return todo;
}
function listTodos() {
  return todos.map(t => ({ ...t }));
}
document.getElementById('add').addEventListener('submit', e => {
  e.preventDefault();
  addTodo(new FormData(e.target).get('text'));
  e.target.reset();
});
